  "steps": [
    {
      "title": "ჩადე სარეცხი",
      "text": "დოლი შეავსე დაახლოებით ⅔-მდე, რომ სარეცხს ტრიალის ადგილი ჰქონდეს. ჯიბეები წინასწარ შეამოწმე.",
      "focus": ["loading_door", "door_handle"],
      "avoid": [],
      "markers": [
        {
          "part": "loading_door",
          "label": "კარი დახურული ჩანს",
          "tone": "neutral"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "მონიშნულია ჩასატვირთად მისადგომი კარი და მისი სახელური. დოლის სრული მოცულობა და ჯიბეების მდგომარეობა არ ჩანს; ⅔-ით შევსება ინსტრუქციის მითითებაა და ფოტოდან ვერ მოწმდება. ეს კვლევითი აღწერაა და არა პროფესიული რჩევა."
    },
    {
      "title": "ჩაასხი სარეცხი საშუალება",
      "text": "ყველაზე დიდ განყოფილებაში (II) ჩაასხი ფხვნილი ან გელი, შეფუთვაზე მითითებული რაოდენობით.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": [],
      "warn": "განყოფილებები ჩანს, მაგრამ „II“ აღნიშვნა არ ჩანს. მხოლოდ ზომით ძირითადი რეცხვის განყოფილება ვერ დადასტურდება, ამიტომ სამიზნე დაუნიშნავია. შეფუთვა და დოზირების მითითებები ფოტოზე არ ჩანს."
    },
    {
      "title": "დაამატე ამაციებელი",
      "text": "თუ გინდა, პატარა განყოფილებაში ჩაასხი ამაციებელი. ეს ნაბიჯი არ არის სავალდებულო.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": [],
      "warn": "დანამატისთვის განკუთვნილი განყოფილების სიმბოლო არ ჩანს. პატარა განყოფილების ზომა ან ლურჯი ჩანართი მის დანიშნულებას ერთმნიშვნელოვნად ვერ ადასტურებს, ამიტომ სამიზნე დაუნიშნავია."
    },
    {
      "title": "აირჩიე პროგრამა",
      "text": "დოლში პირსახოცებს ვხედავ. მოატრიალე სახელური „ბამბაზე“ და დააყენე 60°.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": [],
      "warn": "პირსახოცები და მბრუნავი სახელური ჩანს, თუმცა „ბამბის“ პოზიცია, ტემპერატურის სამართავი და მათი ნიშნები არ ჩანს. სამიზნე პარამეტრები და ბრუნვის მიმართულება ვერ განისაზღვრება. 60° ინსტრუქციის მითითებაა და არა ფოტოდან დადასტურებული პარამეტრი; ქსოვილის შემადგენლობაც უცნობია."
    },
    {
      "title": "დახურე და ჩართე",
      "text": "უჯრა ბოლომდე შეაცურე, კარი დახურე ისე, რომ დაიწკაპუნოს, და დააჭირე სტარტს.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": [],
      "warn": "უჯრა გამოწეულია, კარი კი დახურული ჩანს, თუმცა მისი ჩაკეტვა ფოტოთი ვერ მოწმდება. ღილაკების წარწერები არ ჩანს და „სტარტის“ ღილაკი ვერ ამოიცნობა; ამიტომ ამ ერთობლივი ნაბიჯის ფოკუსი ცარიელია და დასაჭერი ღილაკი არ არის მონიშნული."
    }
  ],
  "unknown_parts": [
    "ძირითადი რეცხვის „II“ განყოფილება — ხილულ განყოფილებებზე შესაბამისი აღნიშვნა არ ჩანს.",
    "დამარბილებლის განყოფილება — შესაბამისი სიმბოლო არ ჩანს და ლურჯი ჩანართის დანიშნულება დაუდასტურებელია.",
    "„ბამბის“ პროგრამის პოზიცია — მბრუნავი სახელურის გარშემო პროგრამების ნიშნები არ ჩანს.",
    "60°-ის ასარჩევი სამართავი — ტემპერატურის აღნიშვნები არ ჩანს და შესაბამისი კონტროლი ვერ ამოიცნობა.",
    "„სტარტის“ ღილაკი — ხილული ღილაკებიდან მისი გამოყოფა წარწერის ან სიმბოლოს გარეშე შეუძლებელია."
  ]
}
